query DocumentsPersonFile($personId: String!) {
    documentsPersonFile(personId: $personId) {
      person { personId name teamName } jobLine hireDate have of hr
      checklist { typeKey name kind state detail documentId requestId dueOn action }
      rows { id title kind typeKey typeName level confidential everyone who { label people { personId name teamName } } subject { personId name teamName } pages mediaType updatedAt expiresOn status { label tone } mine aboutMe deletedAt sectionIds signing { envelopeId status signed of waitingOn canRemind } } types { key name kind filedTo confidential }
    }
  }
